// Unwrap the MCP JSON-RPC envelope into the goal object.
const text = $input.first().json.result.content[0].text;
const data = JSON.parse(text);
return { json: data.data ? data.data : data };

function casRecFrom(row){
  try { return typeof row.record === 'string' ? JSON.parse(row.record) : (row.record || row); }
  catch(e){ return row || {}; }
}
function casUnitIndex(rec){
  // aggregate MF units + nav by ISIN across folios (folios migrate; ISIN is stable)
  var u = {}, nav = {};
  var schemes = (rec && rec.mutualFundSchemes) || [];
  for (var i=0;i<schemes.length;i++){
    var s = schemes[i], isin = s.isin || '';
    if (!isin) continue;
    u[isin] = (u[isin]||0) + (Number(s.units)||0);
    if (Number(s.nav)) nav[isin] = Number(s.nav);
  }
  return { u: u, nav: nav };
}
function casTotalValue(rec){
  var ps = (rec && rec.portfolioSummary) || rec || {};
  return Number(ps.totalPortfolioValue != null ? ps.totalPortfolioValue : (rec||{}).totalPortfolioValue) || 0;
}
// Returns INR figures + USD passive for the transition prevRec -> curRec.
function casPassive(prevRec, curRec, usdinr){
  usdinr = usdinr || 83;
  var p = casUnitIndex(prevRec), c = casUnitIndex(curRec);
  var isins = {};
  Object.keys(p.nav).forEach(function(k){ isins[k]=1; });
  Object.keys(c.nav).forEach(function(k){ isins[k]=1; });
  var netContribINR = 0;
  Object.keys(isins).forEach(function(k){
    var du = (c.u[k]||0) - (p.u[k]||0);
    var navNow = c.nav[k] || p.nav[k] || 0;
    netContribINR += du * navNow;
  });
  var dTotalINR = casTotalValue(curRec) - casTotalValue(prevRec);
  var apprecINR = dTotalINR - netContribINR;              // = Delta-gain (market appreciation only)
  var passiveUSD = Math.round(Math.max(0, apprecINR / usdinr) * 100) / 100;
  return {
    deltaTotalINR: Math.round(dTotalINR),
    netContribINR: Math.round(netContribINR),
    apprecINR: Math.round(apprecINR),
    passiveUSD: passiveUSD
  };
}

function computeFinancials(casRows, tx, trainingRxSrc, targets, usdinr){
  usdinr = usdinr || 83;
  const TRAINING_RX = new RegExp(trainingRxSrc, 'i');

  // passive series from CAS transitions (Delta total value - net SIP contributions)
  const casSorted = (casRows||[]).slice().filter(r=>r&&r.monthKey).sort((a,b)=> a.monthKey<b.monthKey?-1:1);
  const passiveByKey = {}; const passiveSeries = [];
  for (let i=1;i<casSorted.length;i++){
    const r = casPassive(casRecFrom(casSorted[i-1]), casRecFrom(casSorted[i]), usdinr);
    passiveByKey[casSorted[i].monthKey] = r.passiveUSD;
    passiveSeries.push(Object.assign({ monthKey: casSorted[i].monthKey }, r));
  }
  let passiveMonthlyUSD = 0, passiveNote = 'no CAS/portfolio data available';
  if (passiveSeries.length){
    const last = passiveSeries[passiveSeries.length-1];
    passiveMonthlyUSD = last.passiveUSD;
    passiveNote = 'CAS ' + last.monthKey + ': dTotal INR ' + last.deltaTotalINR + ' - contrib INR ' +
      last.netContribINR + ' = passive INR ' + last.apprecINR + ' = USD ' + last.passiveUSD.toFixed(2);
  } else if (casSorted.length === 1){ passiveNote = 'only one CAS month; passive growth unknown'; }

  const rowsAll = (tx||[]).map(t => {
    const m = String(t.Date).match(/(\d{1,2})\/(\d{1,2})\/(\d{4})/);
    return { d: m ? { y:+m[3], mo:+m[1], day:+m[2], key: m[3]+'-'+String(m[1]).padStart(2,'0') } : null,
      desc: String(t['Full Description'] || t.Description || ''),
      hint: String(t['Category Hint'] || ''), amount: Number(t.Amount) || 0 };
  }).filter(r => r.d);

  const daysInMonth = (y,mo) => new Date(y, mo, 0).getDate();
  let minV=null, maxV=null, minD=null, maxD=null;
  for (const r of rowsAll){ const v = r.d.y*10000 + r.d.mo*100 + r.d.day;
    if (minV==null||v<minV){minV=v;minD=r.d;} if (maxV==null||v>maxV){maxV=v;maxD=r.d;} }
  const completeKeys = new Set();
  if (minD && maxD){
    let cy=minD.y, cmo=minD.mo;
    while (cy<maxD.y || (cy===maxD.y && cmo<=maxD.mo)){
      const last = daysInMonth(cy,cmo);
      const startCovered = (minD.y<cy)||(minD.y===cy&&minD.mo<cmo)||(minD.y===cy&&minD.mo===cmo&&minD.day<=1);
      const endCovered   = (maxD.y>cy)||(maxD.y===cy&&maxD.mo>cmo)||(maxD.y===cy&&maxD.mo===cmo&&maxD.day>=last);
      if (startCovered && endCovered) completeKeys.add(cy+'-'+String(cmo).padStart(2,'0'));
      cmo++; if (cmo>12){cmo=1;cy++;}
    }
  }
  const distinctMonths = new Set(rowsAll.map(r=>r.d.key)).size;
  const useComplete = completeKeys.size > 0;
  const rows = useComplete ? rowsAll.filter(r => completeKeys.has(r.d.key)) : rowsAll;
  const divisor = Math.max(1, useComplete ? completeKeys.size : distinctMonths);
  const basisNote = useComplete
    ? (completeKeys.size + ' complete month(s): ' + [...completeKeys].sort().join(', '))
    : (distinctMonths + ' month(s) of partial data (no full month available)');

  const RX_PAYROLL = /payroll|direct dep|\bsalary\b|paycheck|dir dep/i;
  const RX_SAVINGS = /transfer to\b[^]*\bsav|to sav\b|vanguard|fidelity|robinhood|schwab|\broth\b|401k|\bira\b|acorns|betterment|brokerage|wealthfront/i;
  const RX_DEBT    = /card payment|card online payment|citi card|credit card|autopay|amex e?payment|chase credit|discover.*payment|mortgage|\brent\b|auto ?loan|car ?loan|student loan|\bloan\b|\bemi\b/i;
  const RX_INTERNAL= /online transfer to chk|online transfer from|transfer from sav|transfer from chk|real ?time transfer|zelle payment to /i;
  const titleize = s => s.toLowerCase().replace(/_/g,' ').replace(/\b\w/g, c=>c.toUpperCase());
  function classify(r){
    const a = r.amount, hint = r.hint.toUpperCase();
    const primary = hint.split(':')[0].trim(), detailed = (hint.split(':')[1]||'').trim();
    if (primary){
      if (primary === 'INCOME'){ if (a>0 && !/INTEREST|DIVIDEND/.test(detailed)) return { t: TRAINING_RX.test(r.desc)?'training':'payroll', v:a }; return { t:'skip' }; }
      if (primary === 'TRANSFER_IN') return { t:'skip' };
      const abs = a < 0 ? -a : 0;
      if (primary === 'LOAN_PAYMENTS') return { t:'liabilities', v:abs };
      if (detailed === 'RENT_AND_UTILITIES_RENT') return { t:'liabilities', v:abs };
      if (/SAVINGS|INVESTMENT_AND_RETIREMENT/.test(detailed)) return { t:'savings', v:abs };
      if (primary === 'TRANSFER_OUT') return { t:'skip' };
      if (a < 0) return { t:'expenses', v:abs, cat: titleize(primary)||'Other' };
      return { t:'skip' };
    }
    if (a > 0){ if (RX_PAYROLL.test(r.desc)) return { t: TRAINING_RX.test(r.desc)?'training':'payroll', v:a }; return { t:'skip' }; }
    const abs = -a;
    if (RX_SAVINGS.test(r.desc)) return { t:'savings', v:abs };
    if (RX_DEBT.test(r.desc)) return { t:'liabilities', v:abs };
    if (RX_INTERNAL.test(r.desc)) return { t:'skip' };
    return { t:'expenses', v:abs, cat:'Other' };
  }

  const monthAgg = {};
  const bucket = k => monthAgg[k] || (monthAgg[k] = { payroll:0, training:0, expenses:0, liabilities:0, savings:0 });
  for (const r of rowsAll){ const c = classify(r); if (c.t==='skip') continue; bucket(r.d.key)[c.t] += c.v; }

  let lastPassive = 0;
  const monthLabelOf = k => { const p=k.split('-'); return new Date(+p[0],+p[1]-1,1).toLocaleString('en-US',{month:'short',year:'2-digit'}); };
  const byMonth = Object.keys(monthAgg).sort().map(k => {
    const b = monthAgg[k]; const active = b.payroll + b.training;
    if (passiveByKey[k] != null) lastPassive = passiveByKey[k];
    const passive = lastPassive; const income = active + passive;
    const savingsRate = income > 0 ? Math.round(b.savings / income * 100) : 0;
    return { monthKey:k, monthLabel: monthLabelOf(k),
      payroll:Math.round(b.payroll), training:Math.round(b.training), active:Math.round(active),
      passive:Math.round(passive), expenses:Math.round(b.expenses), liabilities:Math.round(b.liabilities),
      savings:Math.round(b.savings), savingsRate,
      trainingTarget: targets.trainingMonthlyUSD, savingsTarget: Math.round(income * targets.savingsRatePct / 100),
      passiveTarget: Math.round(b.expenses) };  // security stage = passive income covers essential expenses
  });
  const trajComplete = byMonth.filter(m => completeKeys.has(m.monthKey));
  const trajectory = (trajComplete.length ? trajComplete : byMonth).slice(-3);

  let payrollSum=0, trainingSum=0, expenseSum=0, liabilitySum=0, savingsSum=0; const catMap={};
  for (const r of rows){ const c = classify(r);
    if (c.t==='payroll') payrollSum += c.v; else if (c.t==='training') trainingSum += c.v;
    else if (c.t==='liabilities') liabilitySum += c.v; else if (c.t==='savings') savingsSum += c.v;
    else if (c.t==='expenses'){ expenseSum += c.v; const k=c.cat||'Other'; catMap[k]=(catMap[k]||0)+c.v; } }
  const per = x => Math.round(x / divisor);
  const computed = {
    payroll: per(payrollSum), training: per(trainingSum), activeIncome: per(payrollSum+trainingSum),
    expenses: per(expenseSum), liabilities: per(liabilitySum), savings: per(savingsSum),
    passiveIncome: Math.round(passiveMonthlyUSD),
    categories: Object.keys(catMap).map(k => ({ name:k, amountUSD: per(catMap[k]) })).sort((a,b)=>b.amountUSD-a.amountUSD).slice(0,6),
    basisNote, hasTx: rows.length > 0 };

  // ---- Category x month x merchant matrix (for answering arbitrary financial queries).
  // Everything is CODE-summed here so the query LLM never re-adds transactions. ----
  function merchOf(desc){
    let s = String(desc||'').toUpperCase().replace(/^APLPAY\s+/,'').replace(/^BT\*/,'').trim();
    const brands = [[/WAL-?MART|WALMART/,'Walmart'],[/AMAZON/,'Amazon'],[/7-?ELEVEN/,'7-Eleven'],[/WAWA/,'Wawa'],
      [/SHEIN/,'SHEIN'],[/TEMU/,'Temu'],[/H&M|HM\.COM/,'H&M'],[/MACY/,"Macy's"],[/COSTCO/,'Costco'],[/TARGET/,'Target'],
      [/DOLLAR ?TREE|DOLLAR ?GENERA/,'Dollar Store'],[/UBER/,'Uber'],[/LYFT/,'Lyft'],[/NETFLIX/,'Netflix'],
      [/SPOTIFY/,'Spotify'],[/STARBUCKS/,'Starbucks'],[/GIFTCARD/,'Giftcards Group'],[/MICRO ?CENTER/,'Micro Center'],
      [/SWAROVSKI/,'Swarovski'],[/CVS/,'CVS'],[/WALGREEN/,'Walgreens'],[/SHELL|EXXON|BP |FUEL/,'Fuel']];
    for (const [rx,name] of brands) if (rx.test(s)) return name;
    return titleize(s.replace(/\s+#?\d{2,}.*$/,'').split(/\s{2,}|\s/).slice(0,3).join(' ')).slice(0,26) || 'Other';
  }
  function labelOf(r, c){
    if (c.t==='payroll') return 'Payroll (income)';
    if (c.t==='training') return 'Training (income)';
    if (c.t==='savings') return 'Savings & Investments';
    if (c.t==='expenses') return c.cat || 'Other';
    if (c.t==='liabilities'){
      const det = (r.hint.toUpperCase().split(':')[1]||'').trim();
      if (det==='RENT_AND_UTILITIES_RENT' || /\bRENT\b/i.test(r.desc)) return 'Rent';
      if (/CREDIT_CARD/.test(det) || /card payment|credit card/i.test(r.desc)) return 'Credit Card Payments';
      if (/MORTGAGE/.test(det) || /mortgage/i.test(r.desc)) return 'Mortgage';
      if (/CAR|AUTO/.test(det) || /auto ?loan|car ?loan/i.test(r.desc)) return 'Car Loan';
      if (/STUDENT/.test(det) || /student loan/i.test(r.desc)) return 'Student Loan';
      return 'Loan / Debt Payments';
    }
    return 'Other';
  }
  const catAgg = {};
  for (const r of rows){
    const c = classify(r); if (c.t==='skip') continue;
    const label = labelOf(r, c); const amt = c.v;
    const e = catAgg[label] || (catAgg[label] = { type:c.t, total:0, count:0, months:{}, merch:{}, largest:null });
    e.total += amt; e.count++; e.months[r.d.key] = (e.months[r.d.key]||0) + amt;
    const m = merchOf(r.desc); e.merch[m] = e.merch[m] || { t:0, c:0 };
    e.merch[m].t += amt; e.merch[m].c++;
    if (!e.largest || amt > e.largest.amount) e.largest = { date:r.d.key, merchant:m, amount:Math.round(amt) };
  }
  const categoryMatrix = Object.keys(catAgg).map(label => {
    const e = catAgg[label];
    const merchants = Object.keys(e.merch).map(m => ({ merchant:m, total:Math.round(e.merch[m].t), count:e.merch[m].c }))
      .sort((a,b)=>b.total-a.total).slice(0,6);
    const months = {}; Object.keys(e.months).sort().forEach(k => { months[k] = Math.round(e.months[k]); });
    return { label, type:e.type, monthlyAvg: per(e.total), count:e.count, months, merchants, largest:e.largest };
  }).sort((a,b)=> b.monthlyAvg - a.monthlyAvg);

  return { byMonth, trajectory, computed, passiveSeries, passiveByKey, passiveMonthlyUSD, passiveNote, basisNote, categoryMatrix };
}

const goal = $('Parse Goal').first().json.goalItemById || {};
let casRows = [], tx = [];
try { casRows = $('Read CAS').all().map(i=>i.json); } catch(e) {}
try { tx = $('Read Last3Months').all().map(i=>i.json); } catch(e) {}
const F = computeFinancials(casRows, tx, "training|course|coaching|workshop|cohort|mentor|tutor|webinar|masterclass|topmate|gumroad|teachable|udemy|thinkific|kajabi|podia|stripe|razorpay|payoneer|paypal|wise ", {"trainingMonthlyUSD": 500, "savingsRatePct": 25}, 83);
const computed = F.computed, trajectory = F.trajectory;

const base = (computed.activeIncome + computed.passiveIncome) ||
             Math.max(1, computed.expenses + computed.liabilities + computed.savings);
const pctOf = x => Math.round(x/base*100);
const t0 = trajectory[0]||{}, tN = trajectory[trajectory.length-1]||{};
const arrow = (a,b)=> b>a?'up':(b<a?'down':'flat');
const trend = trajectory.length>=2
  ? ('Trajectory (' + trajectory[0].monthLabel + '->' + tN.monthLabel + '): savings ' + arrow(t0.savings,tN.savings) +
     ', payroll ' + arrow(t0.payroll,tN.payroll) + ', training ' + arrow(t0.training,tN.training) +
     ', passive ' + arrow(t0.passive,tN.passive) + '.')
  : 'Trajectory: not enough complete months yet.';

const metricsLine =
  'MONTHLY METRICS (already computed - use as-is):\n' +
  '- Active income: $' + computed.activeIncome + ' (payroll $' + computed.payroll + ' + training $' + computed.training + ')\n' +
  '- Passive income: $' + computed.passiveIncome + ' (portfolio appreciation net of new SIP; ' + F.passiveNote + ')\n' +
  '- Expenses: $' + computed.expenses + ' (' + pctOf(computed.expenses) + '% of income)\n' +
  '- Liabilities/debt service: $' + computed.liabilities + ' (' + pctOf(computed.liabilities) + '% of income)\n' +
  '- Savings: $' + computed.savings + ' (' + pctOf(computed.savings) + '% of income)\n' +
  '- Basis: ' + F.basisNote + '\n' + '- ' + trend + '\n' +
  (computed.categories.length ? '- Top expense categories: ' +
     computed.categories.map(c=>c.name+' $'+c.amountUSD).join(', ') + '\n' : '');

const systemPrompt = "## Overview\n\nYou are an expert financial coach and daily task facilitator designed to guide users through the Five Levels of Financial Freedom Framework. Your role is to create personalized, actionable daily tasks that progressively move users toward financial independence and absolute financial freedom.\n\n## The Five Levels of Financial Freedom Framework\n\n### Core Metrics\n- **L** = Liability (% of income/assets)\n- **E** = Expense (% of income)\n- **PI** = Passive Income (% of income)\n- **S** = Savings (% of income)\n- **AI** = Active Income (primary income source)\n- **A** = Assets (net worth)\n\n### Stage 0: Financial Resolution\n**Target Metrics:** 70% L, 30% E, 0% S\n**Objective:** Clear high-priority debt to reduce liability to 40% or increase income to reduce debt ratio\n\n**Key Actions:**\n- Start Emergency Fund (3-6 months of expenses)\n- Implement Snowball or Avalanche debt repayment technique\n- Motivate user around \"paying yourself first\" concept\n- Focus on psychological wins with quick debt payoffs\n\n**Recommended Resources:**\n- *Total Money Makeover* - Dave Ramsey\n- *Think and Grow Rich* - Napoleon Hill\n- Snowball/Avalanche debt methodology\n\n---\n\n### Stage 1: Financial Security\n**Target Metrics:** 40% L, 50% E, 10% S\n**Condition:** Liabilities still exceed assets (L > A), but expenses equal active income (E = AI)\n\n**Key Actions:**\n- Save 10% of active income consistently (\"pay yourself first\")\n- Explain the \"soul purchasing\" concept (why saving is about personal freedom)\n- Begin passive income planning\n- Build emergency fund to 6 months of expenses\n- Develop a comprehensive financial plan\n\n**Daily Focus Areas:**\n- Track spending and optimize expenses\n- Allocate 10% of income to savings automatically\n- Research passive income opportunities aligned with skills\n- Build financial literacy through reading and learning\n\n**Recommended Resources:**\n- *The Richest Man in Babylon* - George S. Clason\n- *The 10X Rule* - Grant Cardone\n- Personal finance fundamentals courses\n\n---\n\n### Stage 2: Financial Vitality\n**Target Metrics:** 33% L, 40% E (\u00b17%), 20% S\n**Condition:** Liabilities still exceed assets (L > A), but expenses now less than active income (E < AI), passive income begins\n\n**Key Actions:**\n- Build synergistic compound asset income streams\n- Understand that money can be created through leverage and systems\n- Develop multiple passive income sources (investments, royalties, businesses)\n- Optimize debt repayment through RDPD (Revised Debt Payment Discipline)\n- Increase savings rate to 20%\n- Begin outsourcing non-core activities\n\n**Daily Focus Areas:**\n- Invest surplus income (20% savings rate)\n- Build first passive income stream\n- Master one investment vehicle (stocks, real estate, digital products, etc.)\n- Develop business/side income concepts\n- Study wealth multiplication strategies\n\n**Recommended Resources:**\n- *Rich Dad Poor Dad* - Robert Kiyosaki\n- *The Four-Hour Work Week* - Tim Ferriss\n- *Cashflow Quadrant* - Robert Kiyosaki\n- *MONEY Master the Game* - Tony Robbins\n- Passive income course specializing in your interest area\n\n---\n\n### Stage 3: Financial Independence\n**Target Metrics:** 33% L, 33% E (\u00b14%), 30% S\n**Condition:** Assets now exceed liabilities (L < A), passive income covers expenses (E = PI), passive income is stable\n\n**Key Actions:**\n- Transition mindset from wealth accumulation to wealth optimization\n- Ensure passive income is sustainable and stable\n- Increase savings rate to 30% for accelerated asset growth\n- Build diversified asset portfolio\n- Plan for lifestyle optimization (not limitation)\n\n**Daily Focus Areas:**\n- Monitor and optimize existing passive income streams\n- Build new complementary income sources\n- Invest aggressively in assets (30% savings rate)\n- Study market trends and investment strategies\n- Plan transition strategies for career flexibility\n\n**Recommended Resources:**\n- *The Unshakeable* - Tony Robbins & Peter Mallouk\n- *The Millionaire Fastlane* - MJ DeMarco\n- Advanced investment and portfolio management courses\n\n---\n\n### Stage 4: Financial Freedom\n**Target Metrics:** 20% L, 20% E (\u00b15%), 55% S\n**Condition:** Passive income exceeds expenses (E < PI), passive income supports investment growth\n\n**Key Actions:**\n- Passive income now covers all lifestyle expenses\n- Reinvest 55% of total income into assets\n- Work becomes optional (continue for growth/purpose, not survival)\n- Leverage passive income to accelerate wealth building\n- Design ideal lifestyle and optimize for fulfillment\n\n**Daily Focus Areas:**\n- Optimize investment portfolio returns\n- Build or expand business ventures (discretionary)\n- Mentor others (compound your impact)\n- Plan philanthropic and legacy goals\n- Develop business/creative projects aligned with passion\n\n**Recommended Resources:**\n- Lifestyle design books and courses\n- Advanced business strategy and scaling\n- Wealth preservation and tax optimization resources\n\n---\n\n### Stage 5: Absolute Financial Freedom\n**Target Metrics:** 0% L, 5% E, 95% S\n**Condition:** No debt, minimal expenses relative to assets, maximum autonomy and choice\n\n**Key Actions:**\n- Achieve complete financial autonomy\n- Work becomes purely optional and passion-driven\n- Design life around purpose and impact (not financial necessity)\n- Focus on legacy and systemic change\n- Explore new frontiers (as framework creator noted: \"rocketship for spreading new life forms\")\n\n**Daily Focus Areas:**\n- Execute on life's mission and purpose\n- Build transformative projects with no ROI requirement\n- Mentor and guide others toward their freedom\n- Create lasting impact and legacy\n- Continuous learning and exploration\n\n**Recommended Resources:**\n- Philosophy and meaning-making literature\n- Advanced entrepreneurship and impact investing\n- Leadership and organizational design courses\n\n---\n\n## AI Task Generation Framework\n\n### When generating daily tasks, use this hierarchy:\n\n1. **Assess Current Stage**\n   - Ask user their current liability %, expense %, and savings %\n   - Identify exact stage: Resolution \u2192 Security \u2192 Vitality \u2192 Independence \u2192 Freedom \u2192 Absolute\n\n2. **Generate Stage-Appropriate Tasks**\n   - Focus on 3-5 daily actionable tasks\n   - Mix tactical (immediate actions) with strategic (long-term positioning)\n   - Ensure tasks compound over time\n\n3. **Task Categories by Stage**\n\n   **Financial Resolution & Security:**\n   - Expense tracking and optimization\n   - Debt payoff progress (snowball/avalanche)\n   - Emergency fund building\n   - Financial literacy (reading/courses)\n   - Income optimization\n\n   **Vitality & Independence:**\n   - Passive income building/optimization\n   - Investment research and allocation\n   - Side income development\n   - Asset portfolio monitoring\n   - Leverage and scaling strategies\n\n   **Freedom & Absolute:**\n   - Portfolio optimization and rebalancing\n   - Business and venture development\n   - Mentor and guide activities\n   - Impact and legacy planning\n   - Lifestyle design and execution\n\n4. **Task Customization**\n   - Incorporate user's profession and skills\n   - Consider their available time commitment\n   - Respect their risk tolerance and values\n   - Account for existing income sources\n   - Build on past successes and learnings\n\n5. **Motivation and Accountability**\n   - Connect tasks to larger vision (why matters)\n   - Celebrate milestone achievements\n   - Use psychological principles (momentum, commitment, identity)\n   - Encourage peer accountability and community\n   - Adjust difficulty as user progresses\n\n---\n\n## Daily Task Template\n\nFor each task, provide:\n\n```\n**Task:** [Clear, actionable task]\n**Stage:** [Which stage this task belongs to]\n**Time Required:** [15 min / 30 min / 1 hour / ongoing]\n**Category:** [Expense Management / Debt Payoff / Income Building / Investing / Learning]\n**Action Steps:**\n1. [Specific action]\n2. [Specific action]\n3. [Specific action]\n\n**Why This Matters:** [Connect to stage progression and financial freedom goal]\n**Success Indicator:** [How to measure completion/success]\n**Resources:** [Specific tools, articles, courses, or templates needed]\n```\n\n---\n\n## Conversation Approach\n\n### Initial Conversation\n1. Welcome user and explain the framework\n2. Ask diagnostic questions to identify their current stage\n3. Share what stage represents and what they're working toward\n4. Celebrate progress to date\n5. Set 30-day and 90-day milestones\n\n### Regular Interaction\n1. Check in on previous day's tasks and learnings\n2. Address blockers or challenges\n3. Adjust tasks based on feedback and circumstances\n4. Introduce new concepts aligned with next stage\n5. Share stories and examples of others at similar stages\n\n### When User Struggles\n1. Validate the difficulty\n2. Break tasks into even smaller micro-habits\n3. Reconnect to emotional \"why\"\n4. Offer alternative approaches\n5. Provide extra resources or accountability structures\n\n### Stage Progression\n1. Acknowledge when user data indicates stage advancement\n2. Celebrate the milestone\n3. Explain next stage in detail\n4. Introduce new task categories\n5. Share new recommended resources\n\n---\n\n## Key Philosophical Principles\n\n1. **Progress Over Perfection** - Consistency beats optimization; imperfect action beats perfect planning\n\n2. **Compound Effect** - Small daily actions compound over months and years into transformation\n\n3. **Mindset Evolution** - Financial freedom is as much psychological as mathematical\n\n4. **Systems Not Goals** - Build systems and habits that naturally produce financial results\n\n5. **Purpose Integration** - Tie financial decisions to personal values and life purpose\n\n6. **Automation and Leverage** - Use technology and systems to reduce friction and increase consistency\n\n7. **Continuous Learning** - Financial mastery requires ongoing education and skill development\n\n8. **Community and Accountability** - Share journey with others, mentor and be mentored\n\n9. **Celebrate Wins** - Acknowledge progress to maintain motivation and momentum\n\n10. **Adaptability** - Adjust strategies based on life changes, market conditions, and new opportunities\n\n---\n\n## Example Daily Tasks by Stage\n\n### Financial Security Stage - Day 1\n- **Task 1:** Log all expenses from yesterday (5 min) - Build awareness\n- **Task 2:** Calculate your current L%, E%, S% based on last month's data (15 min) - Know your baseline\n- **Task 3:** Set up automatic 10% transfer to savings account (10 min) - Start \"paying yourself first\"\n- **Task 4:** Read Chapter 1 of *The Richest Man in Babylon* (20 min) - Build passive income mindset\n- **Task 5:** Identify one expense you could cut this month (10 min) - Increase savings rate\n\n### Vitality Stage - Day 1\n- **Task 1:** Research 3 passive income opportunities in your field (30 min) - Explore options\n- **Task 2:** Model out compound returns on your current 20% savings rate over 10 years (20 min) - Visualize potential\n- **Task 3:** Set up investment account and research your first index fund (30 min) - Take action\n- **Task 4:** Listen to podcast on real estate or stock investing (30 min) - Build knowledge\n- **Task 5:** Calculate your \"financial vitality number\" (monthly expenses for E=PI goal) (15 min) - Set target\n\n### Independence Stage - Day 1\n- **Task 1:** Review passive income streams and measure YTD returns (30 min) - Monitor performance\n- **Task 2:** Model next investment opportunity through 30-year projection (20 min) - Think long-term\n- **Task 3:** Work on second passive income stream development for 1 hour (60 min) - Diversify\n- **Task 4:** Update net worth and celebrate progress (15 min) - Acknowledge wins\n- **Task 5:** Plan one business idea or side project for exploration (30 min) - Prepare for freedom stage\n\n---\n\n## Success Metrics to Track\n\n- **Monthly:** Liability %, Expense %, Savings %, Net Worth, Passive Income Generated\n- **Quarterly:** Stage progression, New income streams created, Habits established\n- **Annually:** Total wealth accumulated, Financial independence score, Impact created\n\n---\n\n## Creator's Note\n\nThis framework reflects a philosophy that financial freedom is not just about numbers, but about reclaiming autonomy, creating options, and eventually having the capacity to spread positive life in the universe. Progress through these stages is progress toward personal liberation and the ability to contribute meaningfully to the world.\n\nYour role is to be a consistent, empathetic guide helping users progress through this journey one daily task at a time.\n\n\n\n---\n\n## OUTPUT CONTRACT (STRICT)\n\nThe system has ALREADY computed the user's monthly financials (shown below in MONTHLY METRICS). Do NOT recompute, restate, or invent any numbers. Using those metrics, return ONLY a single minified JSON object, nothing else:\n{\"stage\":\"resolution|security|vitality|independence|freedom|absolute\",\"stageLabel\":\"short human label\",\"recommendation\":\"one inspiring sentence tied to the numbers and the month-over-month trajectory\",\"actions\":[{\"body\":\"a concrete task to do today\",\"why\":\"why it matters\"}]}\n\nRULES:\n- Choose \"stage\" from the six lowercase keys using the provided metrics (compare liability%, expense%, savings%, passive% against the Five-Levels stage targets).\n- 2-3 short, concrete actions targeting the biggest gap (usually the largest liability, lowest savings, or growing the training-income stream toward its target).\n- If the metrics are all zero (no data), say so honestly in the recommendation. No prose outside the JSON.";
const userMessage =
  'A user is starting their daily CFO routine. Today\'s focus / goal:\n"""\n' + (goal.body||'') + '\n"""\n\n' +
  (computed.hasTx ? metricsLine : 'No transaction data available this period; treat all spending metrics as 0.\n') +
  '\nPick the Five-Levels stage from these metrics, write one inspirational recommendation that references the ' +
  'month-over-month trajectory, and propose 2-3 concrete tasks for today. Return ONLY the JSON object from the output contract.';

// ---- Data pack for answering ANY financial query (all figures precomputed) ----
const cm = F.categoryMatrix || [];
const fmtCat = c => {
  const months = Object.keys(c.months).map(k => k + ' $' + c.months[k]).join(', ');
  const merch = (c.merchants||[]).map(m => m.merchant + ' $' + m.total + (m.count>1 ? (' x'+m.count) : '')).join('; ');
  const lg = c.largest ? (' | largest: ' + c.largest.merchant + ' $' + c.largest.amount + ' (' + c.largest.date + ')') : '';
  return '- ' + c.label + ' [' + c.type + ']: $' + c.monthlyAvg + '/mo, ' + c.count + ' txns; by month: ' + months +
         ' | top merchants: ' + merch + lg;
};
const dataPack =
  metricsLine + '\n' +
  'TRAJECTORY (complete months): ' + (trajectory.map(m=>m.monthLabel+' sav$'+m.savings+'/train$'+m.training+'/pass$'+m.passive).join(' | ') || 'n/a') + '\n\n' +
  'INCOME & SPENDING BY CATEGORY (monthly avg over ' + F.basisNote + '; amounts are magnitudes, income vs outflow given by [type]):\n' +
  (cm.length ? cm.map(fmtCat).join('\n') : '(no categorized data)');
const querySystemPrompt =
  'You are the user\'s personal CFO analyst. Answer their financial question using ONLY the precomputed figures ' +
  'provided - never invent, estimate, or re-sum transactions; every number you cite must appear in the data. ' +
  'Be concise and specific: lead with the direct answer, use a small markdown table when it helps, call out the ' +
  'single biggest driver or any one-off that distorts a category, and end with one actionable takeaway. ' +
  'If the data cannot answer the question, say exactly what is missing. Output GitHub-flavored markdown only (no JSON, no preamble).';
const queryUserMessage =
  'QUESTION (the user\'s goal for today):\n"""\n' + (goal.body||'(no goal text)') + '\n"""\n\n' +
  'FINANCIAL DATA (all figures precomputed - use as-is):\n' + dataPack;

return [{ json: { systemPrompt, userMessage, querySystemPrompt, queryUserMessage, _goal: goal,
  _cas: { passiveMonthlyUSD: F.passiveMonthlyUSD, passiveNote: F.passiveNote, passiveSeries: F.passiveSeries },
  _computed: computed, _byMonth: F.byMonth, _trajectory: trajectory, _categoryMatrix: cm } }];

const resp = $('CFO Agent').first().json;
const raw = (resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
function extractJson(text){
  if (text && typeof text === 'object') return text;
  let s = String(text).replace(/```json/gi,'```').replace(/```/g,'').trim();
  try { return JSON.parse(s); } catch(e){}
  let best=null;
  for (let i=0;i<s.length;i++){ if (s[i] !== '{') continue; let depth=0;
    for (let j=i;j<s.length;j++){ if (s[j]==='{') depth++; else if (s[j]==='}'){ depth--; if(depth===0){
      try { const o=JSON.parse(s.slice(i,j+1)); if(o && (o.metrics||o.actions||o.stage)) best=o; } catch(e){} break; }}}}
  return best;
}
let data = extractJson(raw);
if (!data) data = { stage:'security', stageLabel:'Review needed', recommendation:String(raw).slice(0,400)||'Could not parse coach output.', actions:[] };
const bc = $('Build Context').first().json;
const c = bc._computed || {};
const goal = bc._goal || {};

const num = x => Math.max(0, Math.round((Number(x)||0)));
const payroll = num(c.payroll);
const training = num(c.training);
const activeIncome = num(c.activeIncome);
const passiveIncome = num(c.passiveIncome);
