const totalIncome = activeIncome + passiveIncome;
const base = totalIncome > 0 ? totalIncome : Math.max(1, expenses + liabilities + savings);
const pct = x => Math.round((x / base) * 100);

const metrics = {
  income: 100, active: pct(activeIncome), payroll: pct(payroll), training: pct(training), passive: pct(passiveIncome),
  expense: pct(expenses), liabilities: pct(liabilities), savings: pct(savings),
};
const usdAmounts = { payroll, training, activeIncome, passiveIncome, expenses, liabilities, savings, totalIncome };
const categories = (Array.isArray(c.categories)?c.categories:[]).map(x => ({
  name: String(x.name||'Other'), amountUSD: num(x.amountUSD), pctOfIncome: pct(num(x.amountUSD))
})).slice(0,6);
const actions = Array.isArray(data.actions) ? data.actions.slice(0,3) : [];

return [{ json: {
  stage: data.stage, stageLabel: data.stageLabel, recommendation: data.recommendation,
  metrics, usdAmounts, categories, actions,
  _basis: c.basisNote, _passiveNote: bc._cas ? bc._cas.passiveNote : '',
  _trajectory: bc._trajectory || [], _byMonth: bc._byMonth || [],
  _goal: goal, _goalId: $('Webhook').first().json.query.goal_id
} }];

let answer = '';
try {
  const resp = $('Query Agent').first().json;
  answer = (resp && resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
  answer = String(answer).replace(/```(?:markdown)?/gi,'').trim();
} catch(e) {}
const goal = $('Build Context').first().json._goal || {};
return [{ json: { answer, question: goal.body || '' } }];

