const goal = $('Parse Goal').first().json.goalItemById || {};
const taskId = $('Webhook').first().json.query.goal_id;
const helpers = this.helpers;
const RN = $('API Key').first().json.apiKey;
const MCP = 'https://aicivz8c3l.execute-api.ap-south-1.amazonaws.com/dev/mcp/call';
const CFO_TASKREF = '63b3bcd2617e810008987ef3';
const YEAR_GOAL_ID = '69cff16ea8ae350002e9d9be';
const TARGETS = {"trainingMonthlyUSD": 500, "savingsRatePct": 25};
const gql = async (query, variables) => {
  const args = variables ? { query, variables } : { query };
  const resp = await helpers.httpRequest({ method:'POST', url:MCP,
    headers:{ 'Content-Type':'application/json', 'X-API-Key':RN },
    body:{ jsonrpc:'2.0', method:'tools/call', id:1, params:{ name:'graphql_query', arguments: args } }, json:true });
  return JSON.parse(resp.result.content[0].text);
};
const bc = $('Build Context').first().json;
const tj = (bc._trajectory || []);
const latest = tj[tj.length-1] || {};

const now = $now.setZone('America/New_York');
const todayStr = now.toFormat('dd-MM-yyyy');
const firstWeek = now.day <= 7;

let groups = [];
try { groups = (await gql('query{ monthTaskGoals(date:"' + todayStr + '",taskRef:"' + CFO_TASKREF + '"){ date period goalItems{ id body goalRef } } }')).data.monthTaskGoals || []; } catch(e){}
groups = Array.isArray(groups) ? groups : [groups];
const monthBucket = groups.find(g => g && g.period === 'month');
// CURRENT week bucket: the routine identifies each week by the FRIDAY of that week. Compute the Friday
// of today's week and match it. (Picking the first/greatest-<=today week bucket linked stale weeks -
// e.g. Tue 15-09 belongs to Fri 18-09's week, not the prior 11-09 bucket.)
const toNum = (dmy) => { const p = String(dmy||'').split('-'); return p.length===3 ? (+p[2]*10000 + (+p[1])*100 + (+p[0])) : 0; };
const targetFri = now.plus({ days: 5 - now.weekday }).toFormat('dd-MM-yyyy');  // Luxon weekday: Mon=1..Sun=7, Fri=5
const weekBuckets = groups.filter(g => g && g.period === 'week').sort((a,b)=> toNum(a.date)-toNum(b.date));
let weekBucket = weekBuckets.find(g => g.date === targetFri);
if (!weekBucket) weekBucket = { date: targetFri, period: 'week', goalItems: [] };  // bucket not materialized yet

// resolve today's day goal bucket (goalItemById returns null date/period)
let dayDate = goal.date || todayStr, dayPeriod = goal.period || 'day';
for (const g of groups){ if ((g.goalItems||[]).some(it => it.id === taskId)){ dayDate = g.date; dayPeriod = g.period; break; } }

// Preserve taskRef + tags on EVERY updateGoalItem: updateGoalItem does not retain unspecified fields,
// so a link call that omits taskRef DETACHES the goal from its routine (root cause of the 13-15 Sep
// "not linked to routine" failures). addGoalItem enforces "goalRef provided => isMilestone must be true".
const dayTaskRef = goal.taskRef || CFO_TASKREF;
const dayTags = (Array.isArray(goal.tags) && goal.tags.length) ? goal.tags : ['area:cfo'];
const addGoal = 'mutation($date:String!,$period:String!,$body:String,$taskRef:String,$goalRef:String,$isMilestone:Boolean,$tags:[String]){ addGoalItem(date:$date,period:$period,body:$body,taskRef:$taskRef,goalRef:$goalRef,isMilestone:$isMilestone,tags:$tags,isComplete:false){ id body } }';
const linkGoal = 'mutation($id:ID!,$date:String!,$period:String!,$body:String,$goalRef:String,$taskRef:String,$tags:[String]){ updateGoalItem(id:$id,date:$date,period:$period,body:$body,goalRef:$goalRef,isMilestone:true,taskRef:$taskRef,tags:$tags){ id goalRef taskRef } }';
const linkDay  = 'mutation($id:ID!,$date:String!,$period:String!,$body:String,$goalRef:String,$taskRef:String,$tags:[String]){ updateGoalItem(id:$id,date:$date,period:$period,body:$body,goalRef:$goalRef,taskRef:$taskRef,tags:$tags){ id goalRef taskRef } }';
const out = { firstWeek, dayDate, dayPeriod, targetFri, weekBucketDate:(weekBucket&&weekBucket.date)||null, monthGoalId:null, weekGoalId:null, created:[], linked:[] };

// ---- Month goal: first week of month, idempotent, milestone-linked to the year goal ----
let monthGoalId = null;
if (monthBucket){
  const ex = (monthBucket.goalItems || []).find(it => it && it.id);
  if (ex) monthGoalId = ex.id;
  else if (firstWeek){
    const body = 'Financial security this month: lift savings toward ' + TARGETS.savingsRatePct + '% of income, grow training income toward $' + TARGETS.trainingMonthlyUSD + '/mo, and cut the biggest liability - all in service of paying off India debt.';
    try { const res = await gql(addGoal, { date:monthBucket.date, period:'month', body, taskRef:CFO_TASKREF, goalRef:YEAR_GOAL_ID, isMilestone:true, tags:['area:cfo'] });
      monthGoalId = (res.data && res.data.addGoalItem) ? res.data.addGoalItem.id : null;
      if (monthGoalId) out.created.push('month'); else out.monthErr = JSON.stringify(res.errors||res).slice(0,200); }
    catch(e){ out.monthErr = String(e).slice(0,200); }
  }
}
out.monthGoalId = monthGoalId;

// ---- Week goal: if unset, milestone-linked to the month goal; self-heal an unlinked existing one ----
let weekGoalId = null;
if (weekBucket){
  const ex = (weekBucket.goalItems || []).find(it => it && it.id);
  if (ex){
    weekGoalId = ex.id;
    if (monthGoalId && ex.goalRef !== monthGoalId){
      try { await gql(linkGoal, { id:weekGoalId, date:weekBucket.date, period:'week', body:(ex.body||''), goalRef:monthGoalId, taskRef:CFO_TASKREF, tags:['area:cfo'] }); out.linked.push('week->month'); }
      catch(e){ out.weekLinkErr = String(e).slice(0,200); }
    }
  } else {
    const body = 'This week: move one number the right way - save more, add a training sale, or trim a liability. (Ties to this month\'s financial-security goal.)';
    try { const res = await gql(addGoal, { date:weekBucket.date, period:'week', body, taskRef:CFO_TASKREF, goalRef:(monthGoalId||''), isMilestone: !!monthGoalId, tags:['area:cfo'] });
      weekGoalId = (res.data && res.data.addGoalItem) ? res.data.addGoalItem.id : null;
      if (weekGoalId) out.created.push('week'); else out.weekErr = JSON.stringify(res.errors||res).slice(0,200); }
    catch(e){ out.weekErr = String(e).slice(0,200); }
  }
}
out.weekGoalId = weekGoalId;

// ---- Link today's day goal to the week goal (preserving taskRef + tags so it stays in the routine) ----
if (weekGoalId && goal.goalRef !== weekGoalId){
  try {
    const res = await gql(linkDay, { id:taskId, date:dayDate, period:dayPeriod, body:(goal.body||''), goalRef:weekGoalId, taskRef:dayTaskRef, tags:dayTags });
    out.linkedDay = !!(res.data && res.data.updateGoalItem);
    out.linkedTaskRef = (res.data && res.data.updateGoalItem) ? res.data.updateGoalItem.taskRef : null;
    if (!out.linkedDay) out.linkErr = JSON.stringify(res.errors||res).slice(0,200);
  } catch(e){ out.linkErr = String(e).slice(0,200); }
}
return [{ json: out }];

